"""Constant-time comparison helpers for tokens, MACs and signatures."""

from __future__ import annotations

import hashlib
import hmac


def compare_text(left: str, right: str) -> bool:
    """Compare two strings without leaking their common prefix through timing."""
    return hmac.compare_digest(left.encode("utf-8"), right.encode("utf-8"))


def compare_digest_hex(left: str, right: str) -> bool:
    """Compare two hex digests, normalising both sides first."""
    return hmac.compare_digest(left.strip().lower(), right.strip().lower())


def keyed_digest(key: bytes, message: bytes) -> str:
    """Return a fixed-length HMAC-SHA256 digest for comparison.

    Comparing these instead of raw values keeps both the length and the value
    out of the timing channel.
    """
    return hmac.new(key, message, hashlib.sha256).hexdigest()

"""Default-deny authorisation with an auditable decision record."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Mapping

ROLE_SCOPES: Mapping[str, frozenset[str]] = {
    "reader": frozenset({"read"}),
    "writer": frozenset({"read", "write"}),
    "admin": frozenset({"read", "write", "admin"}),
}


@dataclass(frozen=True, slots=True)
class Decision:
    allowed: bool
    subject: str
    action: str
    reason: str


class Authorizer:
    """Authorises actions against an explicit role-to-scope table."""

    def __init__(self, scopes: Mapping[str, frozenset[str]] | None = None) -> None:
        self._scopes = dict(scopes or ROLE_SCOPES)

    def decide(self, subject: str, role: str, action: str) -> Decision:
        granted = self._scopes.get(role)
        if granted is None:
            return Decision(False, subject, action, "unknown_role")
        if action not in granted:
            return Decision(False, subject, action, "scope_not_granted")
        return Decision(True, subject, action, "granted")

    def require(self, subject: str, role: str, action: str) -> None:
        decision = self.decide(subject, role, action)
        if not decision.allowed:
            raise PermissionError(f"{subject!r} is not allowed to {action!r}")

"""Minimal schema validator for untrusted JSON input.

Deliberately dependency-free: the toolkit ships no runtime dependencies, so this
shows the pattern rather than wrapping a library.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Mapping, Sequence


class ValidationError(ValueError):
    """Raised when input does not satisfy the schema."""


@dataclass(frozen=True, slots=True)
class Field:
    name: str
    kind: type
    required: bool = True
    choices: frozenset[Any] | None = None
    minimum: int | None = None
    maximum: int | None = None


@dataclass(frozen=True, slots=True)
class Schema:
    fields: tuple[Field, ...]
    allow_unknown: bool = False

    def validate(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        if not isinstance(payload, Mapping):
            raise ValidationError("payload must be a mapping")
        known = {item.name for item in self.fields}
        unknown = sorted(set(payload) - known)
        if unknown and not self.allow_unknown:
            raise ValidationError(f"unexpected field(s): {', '.join(unknown)}")
        result: dict[str, Any] = {}
        for item in self.fields:
            if item.name not in payload:
                if item.required:
                    raise ValidationError(f"missing required field: {item.name}")
                continue
            value = payload[item.name]
            if isinstance(value, bool) and item.kind is int:
                raise ValidationError(f"field {item.name} must be an integer, not a boolean")
            if not isinstance(value, item.kind):
                raise ValidationError(f"field {item.name} must be {item.kind.__name__}")
            if item.choices is not None and value not in item.choices:
                raise ValidationError(f"field {item.name} must be one of {sorted(item.choices)}")
            if item.minimum is not None and value < item.minimum:
                raise ValidationError(f"field {item.name} must be >= {item.minimum}")
            if item.maximum is not None and value > item.maximum:
                raise ValidationError(f"field {item.name} must be <= {item.maximum}")
            result[item.name] = value
        return result


USER_SCHEMA = Schema(
    fields=(
        Field("id", int, minimum=1),
        Field("role", str, choices=frozenset({"reader", "writer", "admin"})),
        Field("email", str, maximum=254),
    )
)

"""Service error boundary with an explicit public/internal split."""

from __future__ import annotations

import logging
import uuid
from dataclasses import dataclass
from typing import Any, Callable, TypeVar

logger = logging.getLogger(__name__)

T = TypeVar("T")


@dataclass(frozen=True, slots=True)
class ServiceError(Exception):
    code: str
    public_message: str
    correlation_id: str = ""

    def __str__(self) -> str:
        return f"{self.public_message} (reference {self.correlation_id})" if self.correlation_id else self.public_message


class NotFound(ServiceError):
    def __init__(self, resource: str) -> None:
        super().__init__(code="not_found", public_message=f"{resource} was not found")


class Invalid(ServiceError):
    def __init__(self, detail: str) -> None:
        super().__init__(code="invalid", public_message="the request was rejected")
        self.detail = detail


def handle(operation: Callable[..., T], *args: Any, **kwargs: Any) -> T:
    """Run *operation*, converting internal faults into a ServiceError."""
    correlation = uuid.uuid4().hex[:12]
    try:
        return operation(*args, **kwargs)
    except ServiceError as exc:
        exc.correlation_id = correlation
        logger.warning("rejected operation %s", exc.code, extra={"correlation_id": correlation})
        raise
    except (TimeoutError, ConnectionError) as exc:
        logger.error("dependency failure", extra={"correlation_id": correlation})
        raise ServiceError(
            code="dependency_unavailable",
            public_message="the service is temporarily unavailable",
            correlation_id=correlation,
        ) from exc
    except Exception as exc:
        logger.exception(
            "unhandled error in operation %s", getattr(operation, "__name__", operation),
            extra={"correlation_id": correlation},
        )
        raise ServiceError(
            code="internal_error",
            public_message="the request could not be completed",
            correlation_id=correlation,
        ) from exc

"""Outbound HTTP client with timeouts, bounded retries and redirect limits."""

from __future__ import annotations

import random
from typing import Any, Mapping

import httpx

RETRYABLE_STATUS = frozenset({408, 425, 429, 500, 502, 503, 504})
IDEMPOTENT_METHODS = frozenset({"GET", "HEAD", "OPTIONS", "PUT", "DELETE"})


class UpstreamError(RuntimeError):
    """Raised when the upstream service cannot satisfy the request."""


class ApiClient:
    def __init__(
        self,
        base_url: str,
        *,
        token: str | None = None,
        connect_timeout: float = 5.0,
        read_timeout: float = 30.0,
        max_attempts: int = 3,
    ) -> None:
        headers = {"User-Agent": "opencode-toolkit/1"}
        if token:
            headers["Authorization"] = f"Bearer {token}"
        self._base_url = base_url.rstrip("/")
        self._max_attempts = max(1, max_attempts)
        self._client = httpx.Client(
            base_url=self._base_url,
            headers=headers,
            timeout=httpx.Timeout(read_timeout, connect=connect_timeout),
            follow_redirects=False,
            limits=httpx.Limits(max_connections=20, max_keepalive_connections=10),
        )

    def __enter__(self) -> ApiClient:
        return self

    def __exit__(self, *exc: object) -> None:
        self._client.close()

    def request(
        self,
        method: str,
        path: str,
        *,
        json: Mapping[str, Any] | None = None,
        params: Mapping[str, Any] | None = None,
    ) -> httpx.Response:
        last: Exception | None = None
        for attempt in range(self._max_attempts):
            try:
                response = self._client.request(method.upper(), path, json=json, params=params)
            except httpx.TimeoutException as exc:
                last = exc
            else:
                if response.status_code < 400:
                    return response
                if response.status_code not in RETRYABLE_STATUS:
                    raise UpstreamError(f"upstream returned {response.status_code}")
                last = UpstreamError(f"retryable status {response.status_code}")
            if method.upper() not in IDEMPOTENT_METHODS:
                break
            self._sleep_backoff(attempt)
        raise UpstreamError("upstream request failed after retries") from last

    @staticmethod
    def _sleep_backoff(attempt: int, *, ceiling: float = 8.0) -> None:
        import time

        delay = min(ceiling, 2**attempt) * (0.5 + random.random() / 2)
        time.sleep(delay)

"""Typed configuration from the environment with fail-fast validation."""

from __future__ import annotations
import os
from dataclasses import dataclass
from typing import Mapping

SECRET_FIELDS = frozenset({"database_password", "api_token"})


class ConfigError(RuntimeError):
    """Raised when required configuration is missing or invalid."""


@dataclass(frozen=True, slots=True)
class Config:
    database_url: str
    database_password: str
    request_timeout: float
    debug: bool
    log_level: str

    def redacted(self) -> dict[str, object]:
        return {
            name: ("***" if name in SECRET_FIELDS else getattr(self, name))
            for name in self.__dataclass_fields__
        }


def _require(env: Mapping[str, str], name: str) -> str:
    value = env.get(name, "").strip()
    if not value:
        raise ConfigError(f"required environment variable {name} is missing or empty")
    return value


def _as_bool(value: str, name: str) -> bool:
    lowered = value.strip().lower()
    if lowered in {"1", "true", "yes", "on"}:
        return True
    if lowered in {"0", "false", "no", "off"}:
        return False
    raise ConfigError(f"{name} must be a boolean value, got {value!r}")


def load(env: Mapping[str, str] | None = None) -> Config:
    source = dict(os.environ if env is None else env)
    timeout_text = _require(source, "REQUEST_TIMEOUT")
    try:
        timeout = float(timeout_text)
    except ValueError as exc:
        raise ConfigError(f"REQUEST_TIMEOUT must be a number, got {timeout_text!r}") from exc
    if not 0 < timeout <= 300:
        raise ConfigError("REQUEST_TIMEOUT must be between 0 and 300 seconds")
    level = _require(source, "LOG_LEVEL").upper()
    if level not in {"DEBUG", "INFO", "WARNING", "ERROR"}:
        raise ConfigError(f"LOG_LEVEL must be one of DEBUG, INFO, WARNING, ERROR; got {level}")
    return Config(
        database_url=_require(source, "DATABASE_URL"),
        database_password=_require(source, "DATABASE_PASSWORD"),
        request_timeout=timeout,
        debug=_as_bool(source.get("DEBUG", "false"), "DEBUG"),
        log_level=level,
    )

"""Structured logging with mandatory redaction at the formatter."""

from __future__ import annotations
import json
import logging
import re
import sys
from typing import Any, Mapping

SENSITIVE_KEYS = re.compile(
    r"(?i)(password|passwd|secret|token|api[_-]?key|authorization|cookie|private[_-]?key|session)"
)


def _redact(value: Any, key: str = "") -> Any:
    if key and SENSITIVE_KEYS.search(key):
        return "***redacted***"
    if isinstance(value, Mapping):
        return {str(k): _redact(v, str(k)) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_redact(item) for item in value]
    if isinstance(value, str) and len(value) > 4096:
        return value[:4096] + f"...[truncated {len(value) - 4096} chars]"
    return value


class JsonFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, Any] = {
            "ts": self.formatTime(record, "%Y-%m-%dT%H:%M:%S%z"),
            "level": record.levelname,
            "logger": record.name,
            "message": record.getMessage(),
        }
        context = getattr(record, "context", None)
        if isinstance(context, Mapping):
            payload["context"] = _redact(dict(context))
        if record.exc_info:
            payload["exception_type"] = record.exc_info[0].__name__ if record.exc_info[0] else None
        return json.dumps(_redact(payload), sort_keys=True, ensure_ascii=False)


def configure(level: str = "INFO", *, stream: Any = sys.stderr) -> logging.Logger:
    logger = logging.getLogger("app")
    logger.setLevel(level.upper())
    logger.propagate = False
    handler = logging.StreamHandler(stream)
    handler.setFormatter(JsonFormatter())
    logger.handlers = [handler]
    return logger

"""pytest fixtures: isolation, deterministic time, leak assertions."""

from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Callable, Iterator

import pytest

SENSITIVE_KEYS = ("password", "secret", "token", "api_key", "authorization")


@dataclass(slots=True)
class FakeClock:
    """A monotonic, explicitly advanced clock.

    Injected rather than monkeypatched globally, so timeout logic can still be
    tested by advancing this clock deliberately.
    """

    now: float = 1_700_000_000.0
    _waiters: list[tuple[float, Callable[[], None]]] = field(default_factory=list, repr=False)

    def advance(self, seconds: float) -> None:
        self.now += seconds
        for deadline, callback in list(self._waiters):
            if deadline <= self.now:
                callback()
                self._waiters.remove((deadline, callback))


@pytest.fixture
def clock() -> FakeClock:
    return FakeClock()


@pytest.fixture
def scratch(tmp_path: Any) -> Iterator[Any]:
    """Per-test directory; guaranteed unique, so tests cannot interfere."""
    root = tmp_path / "workspace"
    root.mkdir()
    yield root
    # Deliberately no cleanup failure suppression: a broken teardown must surface.


@pytest.fixture
def assert_no_secret_leak() -> Callable[[Any], None]:
    """Fail the test if *value* would print a secret.

    Applied to assertion payloads so a regression cannot quietly write a
    credential into CI logs.
    """

    def _check(value: Any) -> None:
        rendered = repr(value).lower()
        for key in SENSITIVE_KEYS:
            if key in rendered:
                pytest.fail(f"test payload appears to contain {key!r}; assertions must stay secret-free")

    return _check

/**
 * JWT verification with a pinned algorithm and required claims.
 *
 * Every failure raises: a caller that forgets to check a nullable result would
 * otherwise treat a bad token as anonymous access.
 */
import { jwtVerify, type JWTPayload } from 'jose';

export interface VerifyOptions {
  issuer: string;
  audience: string;
  /** Seconds of clock skew tolerated on exp/nbf. */
  toleranceSeconds?: number;
}

export async function verifyToken(
  token: string,
  key: CryptoKey,
  options: VerifyOptions,
): Promise<JWTPayload> {
  const { payload } = await jwtVerify(token, key, {
    // Never derive the algorithm from the token header.
    algorithms: ['RS256'],
    issuer: options.issuer,
    audience: options.audience,
    clockTolerance: options.toleranceSeconds ?? 5,
    requiredClaims: ['sub', 'exp', 'iat', 'iss', 'aud'],
  });
  return payload;
}

export function hasScope(payload: JWTPayload, scope: string): boolean {
  const granted = payload.scope;
  if (typeof granted !== 'string') {
    return false;
  }
  // Default-deny: an absent or empty scope set grants nothing.
  return granted.split(/\s+/).filter(Boolean).includes(scope);
}

/**
 * Rendering untrusted content safely.
 *
 * `renderText` is the default and needs no sanitiser. `renderHtml` exists only
 * for content that genuinely must contain markup, and it uses an allow-list.
 */
import DOMPurify from 'dompurify';

export const ALLOWED_TAGS = [
  'b', 'i', 'em', 'strong', 'a', 'p', 'br', 'ul', 'ol', 'li', 'code', 'pre',
];

export const ALLOWED_ATTR = ['href', 'title'];

/** Default path: always use this unless markup is explicitly required. */
export function renderText(target: HTMLElement, value: unknown): void {
  target.textContent = typeof value === 'string' ? value : String(value ?? '');
}

/**
 * Allow-list sanitisation. `ALLOW_DATA_ATTR` is off, `ALLOWED_URI_REGEXP`
 * blocks `javascript:` URLs, and hooks are not installed.
 */
export function renderHtml(target: HTMLElement, value: string): void {
  const clean = DOMPurify.sanitize(value, {
    ALLOWED_TAGS,
    ALLOWED_ATTR,
    ALLOW_DATA_ATTR: false,
    ALLOW_ARIA_ATTR: false,
    FORBID_TAGS: ['style', 'script', 'iframe', 'object', 'embed', 'form'],
    FORBID_ATTR: ['style', 'srcset', 'formaction'],
    USE_PROFILES: { html: true },
  });
  target.innerHTML = clean;
}

export function isSafeExternalUrl(value: string): boolean {
  try {
    const url = new URL(value, window.location.origin);
    return url.protocol === 'https:' || url.protocol === 'http:';
  } catch {
    return false;
  }
}

// Graceful shutdown with a bounded drain deadline.
package main

import (
	"context"
	"errors"
	"log/slog"
	"os"
	"os/signal"
	"syscall"
	"time"
)

// Run starts the server and returns when it has drained or the deadline passed.
func Run(srv *Server, drain time.Duration) error {
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	errCh := make(chan error, 1)
	go func() { errCh <- srv.ListenAndServe() }()

	select {
	case err := <-errCh:
		if errors.Is(err, ErrServerClosed) {
			return nil
		}
		return err
	case <-ctx.Done():
		slog.Info("shutdown requested", "drain", drain.String())
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), drain)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return err
	}
	// A second signal forces immediate exit so an operator is never stuck.
	select {
	case err := <-errCh:
		return err
	case <-time.After(2 * time.Second):
		slog.Warn("drain incomplete; exiting")
		return os.ErrDeadlineExceeded
	}
}
